"use client"
import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Field · Lazer DS Starter Kit
 * Figma: Components page, Field set. State: Default, Focus, Error, Disabled.
 * Label, input and helper text. Width fills its parent between 240 and 480.
 */
export interface FieldProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> {
  label: string
  helper?: string
  /** Shown instead of helper and turns the field to the Error state */
  error?: string
  leadingIcon?: React.ReactNode
}

export const Field = React.forwardRef<HTMLInputElement, FieldProps>(
  ({ label, helper, error, leadingIcon, id, className, disabled, ...props }, ref) => {
    const auto = React.useId()
    const inputId = id ?? auto
    const hintId = `${inputId}-hint`
    return (
      <div data-slot="field" className={cn("flex w-full min-w-[240px] max-w-[480px] flex-col gap-[var(--stack-sm)]", className)}>
        <label htmlFor={inputId} className="lz-body-small text-[var(--component-field-label)]">
          {label}
        </label>
        <div
          className={cn(
            "flex items-center gap-[var(--inline-sm)] px-[var(--component-field-padding-inline)] py-[var(--component-field-padding-block)]",
            "rounded-[var(--component-field-radius)] border-[length:var(--stroke-hairline)] border-solid",
            "bg-[var(--component-field-background)] border-[var(--component-field-border)]",
            "focus-within:border-[var(--component-field-border-focus)] focus-within:shadow-[0_0_0_1px_var(--component-field-border-focus)]",
            error && "border-[var(--component-field-error)] focus-within:border-[var(--component-field-error)] focus-within:shadow-[0_0_0_1px_var(--component-field-error)]",
            disabled && "bg-[var(--component-field-background-disabled)] cursor-not-allowed"
          )}
        >
          {leadingIcon ? <span className="inline-flex size-[var(--component-icon-size-md)] text-[var(--text-muted)] [&>svg]:size-full">{leadingIcon}</span> : null}
          <input
            ref={ref}
            id={inputId}
            disabled={disabled}
            aria-invalid={error ? true : undefined}
            aria-describedby={helper || error ? hintId : undefined}
            className="lz-body w-full min-w-0 bg-transparent text-[var(--text-default)] outline-none placeholder:text-[var(--component-field-placeholder)] disabled:cursor-not-allowed"
            {...props}
          />
        </div>
        {error || helper ? (
          <p id={hintId} className={cn("lz-body-small", error ? "text-[var(--component-field-error)]" : "text-[var(--text-muted)]")}>
            {error ?? helper}
          </p>
        ) : null}
      </div>
    )
  }
)
Field.displayName = "Field"
